/**
 * @module O 内容工具箱
 *
 * skill.definition 投影器——把 Resource Graph 中的 skill.definition 节点投影回
 * oblivions/gamedata/skill_definition_config.php 的 PHP 数组形态。
 *
 * 设计意图（执行案 06-P5 §4.3.2）：
 * - P5-2 改用 generatePhpFile API：文件头注入 `// AUTO-GENERATED FROM ...` 注释、
 *   模块标签与 sectionTitle 由 schema.projectionTargets 派生，不再使用硬编码文件头。
 * - skill.definition 节点 id 是 skill_id（与 combat.skill 的 act_id 共享命名空间），
 *   data 是该技能的 identity 元数据（category / lifetime / hidden / equipment_grant /
 *   stacking / duration_ticks / capability_denies 等字段）。
 * - 字段顺序按节点 data 的 key 插入顺序保留——TS 对象保留 string key 顺序，
 *   loader 从 skill_definition_config.php 解析时按文件顺序写入，投影时按图顺序输出。
 * - 嵌套字段（equipment_grant / capability_denies）由 renderPhpValue 递归输出。
 *
 * 字段映射：
 *   - 节点 id              → 顶层 key（skill_id，如 'move' / 'flustered'）
 *   - node.data.{field}    → entry 字段（category / lifetime / hidden / equipment_grant /
 *                            stacking / duration_ticks / capability_denies）
 *
 * 边界：
 * - 节点 data 为 null/非对象时跳过该节点
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 * - 节点 id 必须匹配 /^[a-z][a-z0-9_]*$/，否则跳过（idPattern 校验）
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='skill.definition' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const SKILL_DEFINITION_CONFIG_FILE_PATH = 'oblivions/gamedata/skill_definition_config.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const SKILL_DEFINITION_CONFIG_AUTHOR_SOURCE =
  'oblivions/content/skills/skill-definition-config.yaml';

/** skill.definition 节点 id 正则——与 schema idPattern 对齐 */
const SKILL_DEFINITION_ID_PATTERN = /^[a-z][a-z0-9_]*$/;

/**
 * 把 skill.definition 节点投影回 skill_definition_config.php 形态。
 *
 * @param nodes skill.definition 节点数组（顺序保留为顶层 skill_id 顺序）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/skill_definition_config.php）
 */
export function projectSkillDefinitionConfig(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildSkillDefinitionDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'H 战斗与技能系统',
    sectionTitle: 'Oblivions 技能定义配置表',
    autoGeneratedFrom: SKILL_DEFINITION_CONFIG_AUTHOR_SOURCE,
  });
  return [{ filePath: SKILL_DEFINITION_CONFIG_FILE_PATH, content }];
}

/**
 * 把 skill.definition 节点重建为 skill_definition_config.php 字典形态。
 *
 * 节点 id 作为顶层 key（skill_id），node.data 作为 value（含 category / lifetime /
 * hidden / equipment_grant / stacking / duration_ticks / capability_denies 等字段）。
 * stripUndefinedFields 递归移除 undefined 字段。
 *
 * 嵌套字段（equipment_grant / capability_denies）由 renderPhpValue 递归处理。
 */
function buildSkillDefinitionDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (!SKILL_DEFINITION_ID_PATTERN.test(node.id)) continue;
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const cleaned = stripUndefinedFields(node.data);
    dict[node.id] = cleaned as PhpValue;
  }
  return dict;
}

/**
 * 递归移除 undefined 字段——与 php-adapter.stripUndefinedFields 行为一致。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
